$thickbodyB$, sections = '[{"heading": "Key facts", "summary": ""}, {"heading": "1. What the Regulation does", "summary": "The Regulation has two pillars."}, {"heading": "2. Controls on products entering the Union", "summary": "Customs authorities carry out controls on products entering the Union based on risk analysis, in cooperation with market surveillance authorities."}, {"heading": "3. The EU economic operator requirement", "summary": "For products covered by the listed harmonisation legislation, an economic operator established in the Union must be designated: the manufacturer, the importer, an authorised representative with a written mandate, or..."}, {"heading": "4. Powers on non-compliance", "summary": "Where market surveillance authorities find non-compliance, they have a graduated set of powers."}, {"heading": "5. Who is affected and what to prepare", "summary": "Every importer of products covered by the listed legislation is directly affected, as are non-EU manufacturers whose goods enter the Union, fulfilment service providers handling those goods, and distributors."}, {"heading": "6. What this means for businesses", "summary": "The regulation makes product compliance a logistics variable."}, {"heading": "How the EU compares with other markets", "summary": "The **EU** runs border product-compliance controls through customs and market surveillance cooperation under a single regulation, with the EU-operator requirement as a distinctive feature."}, {"heading": "Official sources", "summary": "Last verified: 2026-09-29."}]'::jsonb, short_answer = 'Regulation (EU) 2019/1020 on market surveillance and compliance of products governs how products entering the Union are checked at the border and how market surveillance authorities cooperate with customs. For importers, it means risk-based controls, possible suspension of release, and a requirement that products in listed categories have an EU-based economic operator.', updated_at = now() WHERE slug = 'eu-market-surveillance-border-controls';